# AUTO-GENERATED by Claude Code
# Purpose: the fonts the app ships (services/ui/assets/nerd_fonts/) are there for every
#          @font-face in app.css, with their license (OFL asks for it to travel with the font).
# Usage: uv run pytest tests/services/ui/test_bundled_fonts.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import re
from pathlib import Path

ASSETS = Path(__file__).resolve().parents[3] / "services" / "ui" / "assets"


def test_every_font_face_points_at_a_bundled_file() -> None:
    css = (ASSETS / "app.css").read_text(encoding="utf-8")
    urls = re.findall(r"@font-face[^}]*url\(\"/([^\"]+)\"\)", css)
    assert urls, "app.css declares no @font-face"
    missing = [url for url in urls if not (ASSETS / url).is_file()]
    assert not missing, f"app.css points at fonts that aren't in services/ui/assets: {missing}"


def test_the_font_license_ships_with_it() -> None:
    assert "SIL Open Font License" in (ASSETS / "nerd_fonts" / "OFL.txt").read_text(encoding="utf-8")


def test_the_release_they_come_from_is_recorded() -> None:
    # `ds ui fonts` compares it with the latest Nerd Fonts release
    assert (ASSETS / "nerd_fonts" / "VERSION").read_text(encoding="utf-8").startswith("v")
